-- Square pictures for the five Instagram profile links (Sean, 2026-11-15: Meta Verified, links can carry pictures; "Yes to both").
-- Files in vegan-media/media/social/bio-links/ (copies in public/social/bio-links/), added to the Social kit's Instagram tab with Save. Safe to run twice.
with pics as (select '[{"label":"Link 1 picture: Join free (Liz)","size":"1080 x 1080","url":"https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/social/bio-links/join-liz.jpg"},{"label":"Link 2 picture: Find Vegan near you (Nori)","size":"1080 x 1080","url":"https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/social/bio-links/near-nori.jpg"},{"label":"Link 3 picture: ThanksLiving Guide (Theo)","size":"1080 x 1080","url":"https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/social/bio-links/thanksliving-theo.jpg"},{"label":"Link 4 picture: Events near you (River)","size":"1080 x 1080","url":"https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/social/bio-links/events-river.jpg"},{"label":"Link 5 picture: The Vegans Explore Podcast (Kai)","size":"1080 x 1080","url":"https://fwbhwfxpncrsfhttimna.supabase.co/storage/v1/object/public/vegan-media/media/social/bio-links/podcast-kai.jpg"}]'::jsonb j)
update ve_brand_cartridges c set data = jsonb_set(c.data, '{social,profiles}', (select jsonb_agg(case when p->>'platform'='Instagram' then jsonb_set(p, '{files}', (select jsonb_agg(f) from jsonb_array_elements(p->'files') f where f->>'label' not like 'Link % picture:%') || pics.j) || '{"note":"Links: the first five in the list below, in order (Instagram allows five): Edit profile > Links, Copy title and Copy link for each, and Save its picture below (Link 1 to 5)."}'::jsonb else p end order by ord) from jsonb_array_elements(c.data->'social'->'profiles') with ordinality t(p, ord))), updated_at = now()
from pics where c.brand_slug = 'vegans-explore';
